import assert from 'node:assert/strict';
import {readFileSync,writeFileSync} from 'node:fs';
import {chromium,webkit} from 'playwright';
import {chapterHash} from '../lib/practice-chapters.ts';
const root='docs/klink10-sentences-20261102',m=JSON.parse(readFileSync(root+'/import-manifest.json')),checks=[],errors=[];
const base=process.env.KLINK_TEST_BASE||'http://127.0.0.1:19041',out=process.env.KLINK_TEST_OUTPUT||root+'/local';
for(const[engine,type]of Object.entries({chromium,webkit})){
 const browser=await type.launch({headless:true,...(engine==='chromium'?{channel:'chrome'}:{})});
 try{for(const width of [390,1280]){
  const theme=width===390?'dark':'light',page=await browser.newPage({viewport:{width,height:844},colorScheme:theme});page.on('pageerror',e=>errors.push(e.message));
  await page.addInitScript(theme=>{localStorage.setItem('taalroute-klink-appearance-v1',theme);localStorage.setItem('klink.exercise-view.v1',JSON.stringify({photo:true,text:false}));window.Audio=class extends EventTarget{dataset={};paused=true;play(){this.paused=false;setTimeout(()=>{this.paused=true;this.dispatchEvent(new Event('ended'));},10);return Promise.resolve();}pause(){this.paused=true;}};},theme);
  async function open(activity,level){const row=m.newRows.find(x=>x.row.activity===activity&&x.row.level===level).row,e=JSON.parse(readFileSync('public'+row.url)).exercises[0];await page.goto(base+'/'+chapterHash({chapter:'sentences',activity,collection:row.id,level,help:'practice'}));await page.locator(`[data-exercise-id="${e.exerciseId}"]`).waitFor();return e;}
  const own=await open('word-sentence','alfa-b');await page.getByRole('button',{name:'Klaar',exact:true}).click();assert(await page.getByRole('button',{name:'Bekijk een voorbeeld',exact:true}).isVisible());assert(await page.locator('[data-practice-next]').isDisabled());
  const spoken=await page.evaluate(id=>JSON.parse(localStorage.getItem('klink.own-sentence.v1:'+id)),own.exerciseId);assert.equal(spoken.first.medium,'spoken');checks.push({engine,width,case:'spoken-self-report-not-automatic-assessment'});
  await page.evaluate(id=>localStorage.removeItem('klink.own-sentence.v1:'+id),own.exerciseId);await page.reload();await page.getByRole('button',{name:'Typ de zin',exact:true}).click();await page.locator('textarea').fill('Dit is mijn eerste zin.');await page.getByRole('button',{name:'Mijn zin is klaar',exact:true}).click();await page.locator('textarea').fill('Dit is mijn verbeterde zin.');await page.reload();await page.locator('textarea').waitFor();assert.equal(await page.locator('textarea').inputValue(),'Dit is mijn verbeterde zin.');assert(await page.getByText('Je eerste eigen zin: Dit is mijn eerste zin.',{exact:true}).isVisible());assert(await page.locator('[data-practice-next]').isDisabled());
  await page.getByRole('button',{name:'Bekijk een voorbeeld',exact:true}).click();await page.waitForFunction(()=>Boolean(window.TaalrouteAppearance));await page.evaluate(theme=>window.TaalrouteAppearance.set(theme),theme);await page.waitForFunction(theme=>document.documentElement.dataset.theme===theme,theme);await page.screenshot({path:`${out}/screens/access-${engine}-${width}-${theme}.png`,fullPage:true});assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1),false);checks.push({engine,width,theme,case:'typed-first-and-revised-draft-survive-reload',horizontalOverflow:false});
  const stage=await open('sentence-build','b1');assert(stage.sequenceStages?.length>1);for(const id of stage.sequenceStages[0].targetOrderIds)await page.locator(`[data-order-item="${id}"]`).click();await page.locator('[data-practice-check]').click();await page.getByRole('button',{name:'Goed. Volgende zin',exact:true}).click();await page.reload();await page.getByText(`Zin 2 van ${stage.sequenceStages.length}`,{exact:true}).waitFor();assert(await page.locator('[data-practice-next]').isDisabled());await page.evaluate(id=>localStorage.setItem('klink.sentence-stages.v1:'+id,'["invalid"]'),stage.exerciseId);await page.reload();await page.getByText(`Zin 1 van ${stage.sequenceStages.length}`,{exact:true}).waitFor();checks.push({engine,width,case:'stage-reload-and-invalid-prefix-reset'});
  const copy=await open('sentence-dictation','alfa-b'),answer=copy.fields[0].acceptedAnswers[0];assert(await page.getByText(answer,{exact:true}).isVisible());const input=page.locator('.cp-text-entry input');await input.fill(answer.toLowerCase().replace(/[.!?]/g,''));await page.locator('[data-practice-check]').click();assert(await page.locator('[data-practice-next]').isDisabled());await input.fill(answer);await page.locator('[data-practice-check]').click();await page.waitForFunction(()=>!document.querySelector('[data-practice-next]').disabled);checks.push({engine,width,case:'copy-model-visible-with-text-off-and-punctuation-required'});
  await page.close();
 }}finally{await browser.close();}
}
assert.equal(checks.length,16);assert.deepEqual(errors,[]);writeFileSync(out+'/access.json',JSON.stringify({checks,errors,physicalMicrophoneTested:false},null,2)+'\n');console.log('Sixteen sentence persistence, oral self-review, copy visibility and theme checks passed.');
